export const getTeamsGetCadenceMetricsUrl = (id: string,
    params?: TeamsGetCadenceMetricsParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/organization/teams/${encodeURIComponent(String(id))}/cadence-metrics?${stringifiedParams}` : `/api/organization/teams/${encodeURIComponent(String(id))}/cadence-metrics`
}

/**
 * A Kanban team's velocity over its reporting cadence: the Requirement-tier work it completed (Done-category status, not Removed) in each recent period, by item count and in the sizing method of the period's operating model, with the average and spread across ended, whole periods. Periods follow each operating model's cadence in that model's time zone; a period cut short where an operating model changes the cadence, time zone or sizing method inside it is partial and left out of the averages, as is the current period. periodWindow is how many ended periods to measure over (3 to 12); omit it for the organization's sprint window. There is no commitment, so no predictability or say/do. A team with no cadence returns no periods. Returns 404 for an id that is not a team's, including a team of teams, which has no cadence.
 * @summary Get the team's cadence velocity.
 */
export const teamsGetCadenceMetrics = async (id: string,
    params?: TeamsGetCadenceMetricsParams, options?: Parameters<typeof apiFetch>[1]): Promise<TeamCadenceMetricsDto> => {

  return apiFetch<TeamCadenceMetricsDto>(getTeamsGetCadenceMetricsUrl(id,params),
  {
    ...options,
    method: 'GET'


  }
);}


export const getTeamsGetFunctionalOrganizationChartUrl = (params?: TeamsGetFunctionalOrganizationChartParams,) => {
const encodedParams = { ...params };
if (encodedParams.asOfDate != null) {
  encodedParams.asOfDate = typeof encodedParams.asOfDate === 'string' ? encodedParams.asOfDate : (String(encodedParams.asOfDate) as unknown as typeof encodedParams.asOfDate);
}
  const normalizedParams = new URLSearchParams();

  Object.entries(encodedParams).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/organization/teams/functional-organization-chart?${stringifiedParams}` : `/api/organization/teams/functional-organization-chart`
}

/**
 * The tree of teams of teams and teams active on `asOfDate` (an ISO 8601 date, its calendar date used; omit for today), placed by their memberships on that day: `organization` holds the top-level units, each with its `id`, `key`, `code`, `type` (Team or Team of Teams), `level` (0 at the top), `path` of codes and `children`; a team with no parent that day is at the top. `total` counts every unit and `maxDepth` is the deepest level. Teams only, not people: for members use Teams_GetMembers.
 * @summary Get the functional organization chart for a given date.
 */
export const teamsGetFunctionalOrganizationChart = async (params?: TeamsGetFunctionalOrganizationChartParams, options?: Parameters<typeof apiFetch>[1]): Promise<FunctionalOrganizationChartDto> => {

  return apiFetch<FunctionalOrganizationChartDto>(getTeamsGetFunctionalOrganizationChartUrl(params),
  {
    ...options,
    method: 'GET'


  }
);}


export const getTeamsGetMembersUrl = (id: string,) => {




  return `/api/organization/teams/${encodeURIComponent(String(id))}/members`
}

/**
 * Takes the team's UUID `id`. One entry per person, by name, with the `employee` (`id` is the employee UUID the member tools take) and every team member `role` they hold on the team. Membership has no dates; the time people give the team is their allocation, under Teams_GetCapacity. An unknown team returns an empty list.
 * @summary Get the members of a team.
 */
export const teamsGetMembers = async (id: string, options?: Parameters<typeof apiFetch>[1]): Promise<TeamMemberDto[]> => {

  return apiFetch<TeamMemberDto[]>(getTeamsGetMembersUrl(id),
  {
    ...options,
    method: 'GET'


  }
);}


export const getTeamsAddMemberUrl = (id: string,) => {




  return `/api/organization/teams/${encodeURIComponent(String(id))}/members`
}

/**
 * Takes the team's UUID `id`, the `employeeId` (employee UUID) and at least one `roleIds` entry: team member role UUIDs from TeamMemberRoles_GetList. The team and the employee must be active. Adding someone who is already a member adds the roles; a role they already hold on the team is refused. Membership does not allocate their time; that is Employees_ChangeAllocations.
 * @summary Add a member to a team.
 */
export const teamsAddMember = async (id: string,
    addTeamMemberRequest: AddTeamMemberRequest, options?: Parameters<typeof apiFetch>[1]): Promise<void> => {

  return apiFetch<void>(getTeamsAddMemberUrl(id),
  {
    ...options,
    method: 'POST',
    headers: getHeaders({ 'Content-Type': 'application/json' }, options?.headers),
    body: JSON.stringify(addTeamMemberRequest)
  }
);}


export const getTeamsUpdateMemberUrl = (id: string,
    employeeId: string,) => {




  return `/api/organization/teams/${encodeURIComponent(String(id))}/members/${encodeURIComponent(String(employeeId))}`
}

/**
 * Takes the team's UUID `id` and the member's `employeeId`. **`roleIds` replaces the member's roles on the team**: roles left out are removed, so pass every role they should keep (at least one; to take them off the team, use Teams_RemoveMember). Read the current roles with Teams_GetMembers first.
 * @summary Update a team member's roles.
 */
export const teamsUpdateMember = async (id: string,
    employeeId: string,
    updateTeamMemberRequest: UpdateTeamMemberRequest, options?: Parameters<typeof apiFetch>[1]): Promise<void> => {

  return apiFetch<void>(getTeamsUpdateMemberUrl(id,employeeId),
  {
    ...options,
    method: 'PUT',
    headers: getHeaders({ 'Content-Type': 'application/json' }, options?.headers),
    body: JSON.stringify(updateTeamMemberRequest)
  }
);}


